import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    p = input_data[1]

    if n <= 1:
        print('*')
        return

    # Total counts of each character
    total_counts = [0] * 26
    for ch in p:
        total_counts[ord(ch) - 97] += 1

    # Find all proper divisors of n
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i * i != n and i != 1:
                divisors.append(n // i)
    divisors.sort()

    for L in divisors:
        k = n // L
        # Check if total counts are compatible with k identical anagram blocks
        root = p[:L]
        root_counts = [0] * 26
        for ch in root:
            root_counts[ord(ch) - 97] += 1

        possible = True
        for c in range(26):
            if total_counts[c] != root_counts[c] * k:
                possible = False
                break

        if not possible:
            continue

        # Verify each of the remaining blocks
        is_polygram = True
        for i in range(1, k):
            block = p[i * L : (i + 1) * L]
            block_counts = [0] * 26
            for ch in block:
                block_counts[ord(ch) - 97] += 1
            if block_counts != root_counts:
                is_polygram = False
                break

        if is_polygram:
            print(root)
            return

    print('*')

if __name__ == '__main__':
    solve()
